 try:
  with core.tx() as c:
   c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(b['username'],b['password'],b.get('display_name') or b['username']))
   uid=c.lastrowid; t=__import__('secrets').token_urlsafe(24); c.execute('INSERT INTO tokens VALUES(?,?)',(t,uid)); u=c.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone()
